// Extension → category for colours and the file type summary.
const EXT_CATEGORY = (() => {
  const groups = {
    video: "mp4 mkv avi mov wmv flv webm m4v mpg mpeg m2ts mts ts vob 3gp",
    image: "jpg jpeg png gif bmp tif tiff webp heic heif raw cr2 cr3 nef arw dng psd ico svg avif",
    audio: "mp3 wav flac aac ogg m4a wma opus aiff alac mid",
    archive: "zip rar 7z gz tgz bz2 xz zst tar cab iso img vhd vhdx vmdk qcow2 wim esd dmg pak",
    doc: "pdf doc docx xls xlsx xlsm ppt pptx odt ods odp rtf txt md epub msg eml pst ost one vsdx",
    code: "js ts jsx tsx py go rs c h cpp hpp cs java kt php rb html htm css scss json xml yaml yml toml ini cfg log sh ps1 bat cmd sql lua",
    data: "db sqlite sqlite3 mdb accdb mdf ldf ndf bak dat csv parquet edb jet",
    system: "exe dll sys msi msp drv ocx mui cat pdb lib obj so dylib bin pf etl evtx tmp dmp jar apk appx msix",
  };
  const m = {};
  for (const [cat, list] of Object.entries(groups)) for (const e of list.split(" ")) m[e] = cat;
  return m;
})();
const CATEGORIES = ["video", "image", "audio", "archive", "doc", "code", "data", "system", "other"];
